package com.nextrade.domain.order; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; import java.time.*;
public record Trade(TradeId id,OrderId buyOrderId,OrderId sellOrderId,UserId buyer,UserId seller,InstrumentId instrumentId,Quantity quantity,Price price,Instant executedAt,long sequence){public Trade{if(id==null||buyOrderId==null||sellOrderId==null)throw new IllegalArgumentException("IDs required");if(quantity==null||quantity.isZero())throw new IllegalArgumentException("quantity");if(price==null)throw new IllegalArgumentException("price");if(executedAt==null)executedAt=Instant.now();}}